namespace CsAgentUI;

public static class StaticAssets
{
    public const string HtmlUI = """
    <!DOCTYPE html>
    <html lang="en">
    <head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>CSAgent Console</title>

    <!-- Prism.js for syntax highlighting -->
    <link href="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/themes/prism.min.css" rel="stylesheet" />
    <link href="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/plugins/toolbar/prism-toolbar.min.css" rel="stylesheet" />

    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap" rel="stylesheet">

    <style>
    :root{
        --bg:#070b14;
        --panel:rgba(18,25,38,.85);
        --border:rgba(255,255,255,.10);
        --primary:#4da3ff;
        --primary-glow:rgba(77,163,255,.35);
        --text:#f8fafc;
        --muted:#94a3b8;
        --thought:#fbbf24;
        --call:#38bdf8;
        --result:#4ade80;
        --done:#22c55e;
        --warning:#f59e0b;
        --danger:#ef4444;
    }

    *{
        box-sizing:border-box;
    }

    body{
        margin:0;
        height:100vh;
        display:flex;
        align-items:center;
        justify-content:center;
        padding:25px;
        background:radial-gradient(circle at top,#172033,#070b14 65%);
        color:var(--text);
        font-family:Inter,system-ui,sans-serif;
    }

    .container{
        width:100%;
        max-width:1280px;
        height:90vh;
        display:flex;
        flex-direction:column;
        background:linear-gradient(145deg,rgba(255,255,255,.06),rgba(255,255,255,.01)),var(--panel);
        backdrop-filter:blur(20px);
        border:1px solid var(--border);
        border-radius:22px;
        overflow:hidden;
        box-shadow:0 35px 90px rgba(0,0,0,.65);
    }

    header{
        height:75px;
        padding:0 30px;
        display:flex;
        align-items:center;
        justify-content:space-between;
        border-bottom:1px solid var(--border);
        background:rgba(255,255,255,.03);
    }

    .brand{
        display:flex;
        align-items:center;
        gap:14px;
    }

    h2{
        margin:0;
        display:flex;
        align-items:center;
        gap:10px;
        font-family:"JetBrains Mono",monospace;
        font-size:15px;
        letter-spacing:1px;
    }

    .version{
        color:var(--muted);
        font-size:12px;
    }

    .status{
        display:flex;
        align-items:center;
        gap:8px;
        padding:7px 14px;
        border-radius:20px;
        font-family:"JetBrains Mono",monospace;
        font-size:12px;
        color:#86efac;
        background:rgba(34,197,94,.1);
        border:1px solid rgba(34,197,94,.25);
    }

    .status-dot{
        width:9px;
        height:9px;
        background:var(--done);
